"""probe_rushes.py and prepare_audio.py on tiny files generated by ffmpeg (skipped without ffmpeg)."""
import os
import subprocess
import unittest

from helpers import SETTINGS, TempDirTest, clips_data, needs_ffmpeg, read_json, write_json


def make_video(path, fps, size, seconds, created=None):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    cmd = ["ffmpeg", "-v", "error", "-y", "-f", "lavfi", "-i", f"testsrc=size={size}:rate={fps}:duration={seconds}",
           "-f", "lavfi", "-i", f"sine=frequency=440:duration={seconds}", "-shortest",
           "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p", "-c:a", "aac"]
    if created:
        cmd += ["-metadata", f"creation_time={created}"]
    subprocess.run(cmd + [path], check=True)


def make_audio(path, seconds, rate=48000):
    subprocess.run(["ffmpeg", "-v", "error", "-y", "-f", "lavfi", "-i", f"sine=frequency=300:sample_rate={rate}",
                    "-t", f"{seconds}", "-c:a", "pcm_s16le", path], check=True)


@needs_ffmpeg
class Inventory(TempDirTest):
    @classmethod
    def setUpClass(cls):
        import tempfile
        cls.media = tempfile.mkdtemp(prefix="resolve-edit-media-")
        r = os.path.join(cls.media, "rushes")
        make_video(os.path.join(r, "camA", "A0001.MP4"), 25, "320x180", 2, "2026-01-01T10:00:00Z")
        make_video(os.path.join(r, "camA", "day2", "A0003.MP4"), 25, "320x180", 2, "2026-01-01T09:59:00Z")
        make_video(os.path.join(r, "CAMB", "B_20260101_002.MP4"), 50, "640x360", 4, "2026-01-01T10:00:05Z")
        make_video(os.path.join(r, "camA", "A0005.MP4"), 25, "320x180", 2, "2026-01-01T10:00:06Z")  # during B002
        make_video(os.path.join(r, "camA", "A0009.MP4"), 25, "320x180", 1)                          # no time
        for sidecar in ("camA/A0001M01.XML", "CAMB/B_20260101_002.WAV", "CAMB/B_20260101_002.LRF", ".hidden.MP4"):
            with open(os.path.join(r, sidecar), "w") as f:
                f.write("x")

    @classmethod
    def tearDownClass(cls):
        import shutil
        shutil.rmtree(cls.media, ignore_errors=True)

    def probe(self, settings=None):
        prof = self.profile
        if settings is not None:
            prof = self.path("profile2")
            write_json(os.path.join(prof, "settings.json"), settings)
        p = self.run_script("probe_rushes.py", os.path.join(self.media, "rushes"), "rushes.json", "--profile", prof)
        return read_json(self.path("rushes.json")), p.stdout

    def test_every_sub_folder_cameras_short_names_order(self):
        inv, out = self.probe()
        names = [r["short"] for r in inv["rushes"]]
        # A0009 has no recording time: its file date (now) puts it last
        self.assertEqual(names, ["A0003", "A0001", "B002", "A0005", "A0009"])
        self.assertEqual({r["short"]: r["camera"] for r in inv["rushes"]}["B002"], "Cam B")
        self.assertEqual(inv["rushes"][0]["file"], "camA/day2/A0003.MP4")
        self.assertEqual([r["fps"] for r in inv["rushes"]][:3], [25.0, 25.0, 50.0])
        self.assertEqual(inv["cameras"], ["Cam A", "Cam B"])

    def test_sidecars_and_hidden_files_are_skipped(self):
        inv, _ = self.probe()
        self.assertEqual(len(inv["rushes"]), 5)
        self.assertEqual(sum(inv["skipped"].values()), 4)

    def test_reference_format_is_the_lowest_common_one(self):
        inv, _ = self.probe()
        self.assertEqual(inv["timeline"]["fps"], 25)
        self.assertEqual((inv["timeline"]["width"], inv["timeline"]["height"]), (320, 180))
        self.assertIn("lowest common rate of 25p, 50p", inv["timeline"]["why"])

    def test_warnings(self):
        inv, _ = self.probe()
        w = "\n".join(inv["warnings"])
        self.assertIn("B002 (Cam B) and A0005 (Cam A) overlap by 3s: cameras filming AT THE SAME TIME", w)
        self.assertIn("A0009.MP4: no recording time in the file", w)
        self.assertIn("several cameras", w)
        self.assertIn("mixed frame sizes", w)

    def test_clock_offset_moves_a_camera(self):
        settings = dict(SETTINGS, cameras=[dict(SETTINGS["cameras"][0]),
                                           dict(SETTINGS["cameras"][1], clock_offset=-3600)])
        inv, _ = self.probe(settings)
        self.assertEqual(inv["rushes"][0]["short"], "B002")             # one hour earlier: now first
        self.assertEqual(inv["rushes"][0]["clock_offset"], -3600.0)

    def test_unknown_camera_without_profile(self):
        inv, _ = self.probe({"language": "en"})
        b = [r for r in inv["rushes"] if r["name"] == "B_20260101_002.MP4"][0]
        self.assertEqual(b["short"], "B_20260101_002")                  # file stem
        self.assertTrue(b["camera"])                                     # named after its metadata

    def test_empty_folder(self):
        os.makedirs(self.path("none"))
        p = self.run_script("probe_rushes.py", self.path("none"), "r.json", "--profile", self.profile, check=False)
        self.assertNotEqual(p.returncode, 0)
        self.assertIn("No video file found", p.stdout + p.stderr)


@needs_ffmpeg
class AudioParts(TempDirTest):
    def setUp(self):
        super().setUp()
        # rushes of 2 s, 2 s and 1.5 s: 5.5 s
        write_json(self.path("clips.json"), clips_data([("A.MP4", 50), ("B.MP4", 50), ("C.MP4", 38)]))

    def test_split_at_rush_boundaries_under_the_limit(self):
        make_audio(self.path("ref.wav"), 138 / 25)
        self.run_script("prepare_audio.py", "ref.wav", "clips.json", "parts", "--max-seconds", "3")
        m = read_json(self.path("parts", "manifest.json"))
        self.assertEqual([(x["offset"], x["duration"], x["first_rush"]) for x in m],
                         [(0.0, 2.0, "A.MP4"), (2.0, 2.0, "B.MP4"), (4.0, 1.52, "C.MP4")])
        for x in m:  # 16 kHz mono, sample-exact
            info = subprocess.run(["ffprobe", "-v", "error", "-show_entries", "stream=sample_rate,channels,duration_ts",
                                   "-of", "csv=p=0", x["file"]], capture_output=True, text=True).stdout.strip()
            self.assertEqual(info, f"16000,1,{round(x['duration'] * 16000)}")
        self.assertFalse(os.path.exists(self.path("parts", "ref16k_full.wav")))

    def test_short_audio_stays_in_one_part(self):
        make_audio(self.path("ref.wav"), 138 / 25)
        self.run_script("prepare_audio.py", "ref.wav", "clips.json", "parts")
        m = read_json(self.path("parts", "manifest.json"))
        self.assertEqual(len(m), 1)
        self.assertTrue(m[0]["file"].endswith("ref16k_full.wav"))

    def test_audio_of_the_wrong_length_is_refused(self):
        make_audio(self.path("ref.wav"), 4.0)
        p = self.run_script("prepare_audio.py", "ref.wav", "clips.json", "parts", check=False)
        self.assertNotEqual(p.returncode, 0)
        self.assertIn("export the WHOLE reference timeline", p.stdout + p.stderr)

    def test_rush_longer_than_the_limit_is_refused(self):
        make_audio(self.path("ref.wav"), 138 / 25)
        p = self.run_script("prepare_audio.py", "ref.wav", "clips.json", "parts", "--max-seconds", "1.5", check=False)
        self.assertNotEqual(p.returncode, 0)
        self.assertIn("single rush is longer", p.stdout + p.stderr)


if __name__ == "__main__":
    unittest.main()
